  tableFromArrays,
  Float64,
  Int32,
  Utf8,
  Field,
  Schema,
  Null,
} from "apache-arrow";
import initWasm, { Table as WasmTable, writeParquet } from "parquet-wasm/esm";

// ============================================
// Types — flattened row types for Parquet
// ============================================

export interface DailySleepRow {
  day: string;
  score: number | null;
  deep_sleep: number | null;
  efficiency: number | null;
  latency: number | null;
  rem_sleep: number | null;
  restfulness: number | null;
  timing: number | null;
