import { tableToIPC, tableFromArrays, Float64, Int32, Utf8, Field, Schema } from "apache-arrow";
import { initSync, Table as WasmTable, writeParquet } from "parquet-wasm/esm";

// ============================================
// Types — flattened row types for Parquet
// ============================================

export interface DailySleepRow {
  day: string;
  score: number | null;
  deep_sleep: number | null;
  efficiency: number | null;
  latency: number | null;
  rem_sleep: number | null;
  restfulness: number | null;
  timing: number | null;
  total_sleep: number | null;
  timestamp: string;
  synced_at: string;
}

export interface DailyActivityRow {
  day: string;
  score: number | null;
  active_calories: number | null;
  total_calories: number | null;
  steps: number | null;
  equivalent_walking_distance: number | null;
  high_activity_time: number | null;
  medium_activity_time: number | null;
  low_activity_time: number | null;
  sedentary_time: number | null;
  resting_time: number | null;
  met_average: number | null;
  meet_daily_targets: number | null;
  move_every_hour: number | null;
  recovery_time: number | null;
  stay_active: number | null;
  training_frequency: number | null;
  training_volume: number | null;
  timestamp: string;
  synced_at: string;
}

export interface DailyReadinessRow {
  day: string;
  score: number | null;
  temperature_deviation: number | null;
  temperature_trend_deviation: number | null;
  activity_balance: number | null;
  body_temperature: number | null;
  hrv_balance: number | null;
  previous_day_activity: number | null;
  previous_night: number | null;
  recovery_index: number | null;
  resting_heart_rate: number | null;
  sleep_balance: number | null;
  timestamp: string;
  synced_at: string;
}

export interface HeartRateRow {
  bpm: number;
  source: string;
  timestamp: string;
  day: string;
  synced_at: string;
}

// ============================================
// WASM initialization
// ============================================

let wasmInitialized = false;

function ensureWasmInit(): void {
  if (wasmInitialized) return;

  if (PARQUET_WASM) {
    // Workers runtime: WASM already loaded as static import
    initSync({ module: PARQUET_WASM });
  } else {
    // Node.js (test): load WASM from filesystem
    // biome-ignore lint/style/noVar: dynamic require for Node.js compatibility
    // biome-ignore lint/correctness/noUndeclaredVariables: Node.js global
    const fs = require("node:fs");
    const path = require("node:path");
    const wasmPath = path.resolve(
      __dirname,
      "../../../node_modules/parquet-wasm/esm/parquet_wasm_bg.wasm"
    );
    const wasmBytes = fs.readFileSync(wasmPath);
    initSync({ module: wasmBytes });
  }
  wasmInitialized = true;
}

// ============================================
// Column extraction helpers
// ============================================

function extractColumn<T, K extends keyof T>(rows: T[], key: K): T[K][] {
  return rows.map((r) => r[key]);
}

// ============================================
// Encode functions
// ============================================

function arrowToParquet(schema: Schema, columns: Record<string, unknown[]>): Uint8Array {
  const arrowTable = tableFromArrays(columns);
  const ipcBytes = tableToIPC(arrowTable, "stream");
  const wasmTable = WasmTable.fromIPCStream(ipcBytes);
  return writeParquet(wasmTable);
}

