    });

    fetchMock
      .get("https://api.github.com")
      .intercept({ path: "/users/ta93abe/repos?per_page=100&sort=pushed" })
      .reply(200, [
        {
          id: 1,
          name: "test-repo",
          full_name: "ta93abe/test-repo",
          description: "A test repo",
          language: "TypeScript",
          stargazers_count: 10,
