    new Field("total_sleep", new Int32(), true),
    new Field("timestamp", new Utf8(), false),
    new Field("synced_at", new Utf8(), false),
  ]);

  return arrowToParquet(schema, {
    day: extractColumn(rows, "day"),
    score: extractColumn(rows, "score"),
