import { Hono } from "hono";
// @ts-expect-error — Wrangler bundles .wasm as WebAssembly.Module
import PARQUET_WASM from "../../node_modules/parquet-wasm/esm/parquet_wasm_bg.wasm";
import type { Env, SyncResult } from "../types";
import {
  type DailyActivityRow,
  type DailyReadinessRow,
  type DailySleepRow,
  encodeDailyActivity,
  encodeDailyReadiness,
  encodeDailySleep,
  encodeHeartRate,
  type HeartRateRow,
  initParquetWasm,
} from "./parquet";

const app = new Hono<{ Bindings: Env }>();

const OURA_AUTH_URL = "https://cloud.ouraring.com/oauth/authorize";
const OURA_TOKEN_URL = "https://api.ouraring.com/oauth/token";
const OURA_API_BASE = "https://api.ouraring.com";

// ============================================
// Types
// ============================================

interface OuraTokenResponse {
  access_token: string;
  refresh_token: string;
  token_type: string;
  expires_in: number;
  scope?: string;
}

interface OuraResponse<T> {
  data: T[];
  next_token?: string;
}

interface OuraDailySleep {
  id: string;
  day: string;
  score: number | null;
  timestamp: string;
  contributors?: {
    deep_sleep?: number | null;
    efficiency?: number | null;
    latency?: number | null;
    rem_sleep?: number | null;
    restfulness?: number | null;
    timing?: number | null;
    total_sleep?: number | null;
  };
}

interface OuraDailyActivity {
  id: string;
  day: string;
  score: number | null;
  active_calories: number;
  total_calories: number;
  steps: number;
  equivalent_walking_distance: number;
  high_activity_time: number;
  medium_activity_time: number;
  low_activity_time: number;
  sedentary_time: number;
  resting_time: number;
  average_met_minutes?: number;
  contributors?: {
